const e=[{id:"gas-detection",accent:"#38bdf8",title:"气体检验",tagline:"颜色、气味、木条、石灰水、品红和白烟共同构成高中最典型的气体证据链。",principle:"先根据物理性质做初步预判，再利用专属性反应让目标气体在试纸、木条、检验液或对照现象中显现出来。",signalProfile:[84,61,92,78,68,88,74],controlProfile:[{label:"判据专属性",value:93},{label:"收集适配度",value:86},{label:"尾气闭环",value:89}],workflow:["先看颜色、气味和溶解性","再选收集方式与是否验纯","按目标气体做专属性检验","最后回到尾气吸收和结论表达"],interpretation:["CO2、SO2、Cl2、NH3 虽都可让体系发生可见变化，但判别关键在“专属性证据”和“顺序排除”。","NO 和 NO2 是否接触空气，会直接改变看到的颜色和最终判断。","气体检验结论必须和装置、收集方式、尾气处理放在同一条逻辑里。"],signals:["颜色","气味","湿润试纸","木条","石灰水","品红","白烟"],typicalCase:{title:"SO2 与 CO2 的连续检验",clue:"混合气体先使品红褪色，再经氧化处理后通石灰水仍变浑浊。",answer:"先用品红或酸性 KMnO4 锁定并除去 SO2，再对余气做 CO2 检验。"},classroomPack:{toneLabel:"气体镜头",title:"气体不是“通一下试剂”，而是一条连续证据链",subtitle:"颜色、气味、试纸、木条和尾气吸收一起出现时，气体检验才真正讲清楚。",lead:"同样是放气，为什么有的要先验纯，有的要先酸化，有的要先排空气，本质都落在证据专属性和条件边界上。",scenes:[{id:"sample",label:"样品镜头",accent:"#7dd3fc",title:"先看“它看起来像什么”",details:["黄绿色刺激性气体优先想到 Cl2，红棕色常先想到 NO2。","无色并不意味着信息少，CO2、NH3、SO2、NO 都要靠后续检验区分。","第一眼预判只负责缩小范围，不负责直接下结论。"]},{id:"signal",label:"信号镜头",accent:"#86efac",title:"专属性检验必须分步完成",details:["木条、试纸、石灰水、品红、白烟各自回答不同问题。","有些现象只能说明“有变化”，不能单独说明“是什么气体”。","二次确认和干扰排除是气体检验里最有教学价值的一层。"]},{id:"conclusion",label:"结论镜头",accent:"#fbbf24",title:"结论要连同顺序和边界一起说",details:["SO2 与 Cl2 都能使有色物质褪色，但本质不同，区分方法也不同。","NO 必须把是否接触空气写进结论句，否则现象会被解释错。","检验完成后还要回到尾气吸收和装置目的，形成完整闭环。"]}],flowSteps:["先做样品预判","再做专属性检验","回头排除干扰","最后补上装置与安全闭环"],boardAnchors:["气体检验要先预判再专检","结论必须带顺序和条件","尾气吸收也是检验逻辑的一部分"],misconceptions:["看到褪色就直接说有漂白性。","NO 和 NO2 不区分是否接触空气。","只报结论，不写检验顺序。"],bridgeNote:"可联动无机图谱中的 Cl、S、N、C 主线，也可接方程式库里的气体制备与检验表达。"},pitfalls:["只记石灰水不做干扰排除。","忽略尾气吸收。","把褪色一概归为漂白。"]},{id:"ion-analysis",accent:"#8b5cf6",title:"离子检验",tagline:"酸化、沉淀、显色、加热和前处理共同构成高中无机离子检验的主干路径。",principle:"离子检验的核心不是“背试剂”，而是通过前处理排除干扰，再让目标离子给出尽可能专一的颜色、沉淀或气体现象。",signalProfile:[78,88,66,83,94,72,81],controlProfile:[{label:"前处理完整度",value:95},{label:"现象专一性",value:88},{label:"干扰排除力",value:92}],workflow:["先判断可能干扰","完成酸化或前处理","加入专属性试剂","把现象与目标离子逐一对应"],interpretation:["Cl-、SO4^2-、NH4+、Fe3+、CO3^2- 这类经典离子，真正难点都在顺序和干扰排除。","白色沉淀、放气、显色都只是证据外壳，关键要说明为什么其它粒子被排除了。","离子检验完整表达应包含前处理、操作顺序、现象和判定四个部分。"],signals:["酸化","沉淀颜色","显色","加碱加热","顺序","对照","干扰排除"],typicalCase:{title:"Cl- 与 SO4^2- 的分步检验",clue:"样品可能同时含有 CO3^2-、SO3^2- 等干扰离子，直接加试剂会得到错误现象。",answer:"先酸化排除干扰，再分别进行 AgNO3 和 Ba2+ 检验，并把试剂顺序写完整。"},classroomPack:{toneLabel:"离子镜头",title:"离子检验真正难在“先做什么，后做什么”",subtitle:"把前处理、专检、干扰排除和结论表达并在一起，学生才会真正明白离子检验。",lead:"检验题最容易错的不是“不知道试剂”，而是知道试剂却不知道为什么要先酸化、为什么要先加碱并加热。",scenes:[{id:"sample",label:"样品镜头",accent:"#7dd3fc",title:"未知样品先想谁会干扰",details:["白色沉淀和放气往往不只对应一种离子。","拿到样品后，先考虑哪些粒子会抢先给出现象。","只有先想干扰，后面的检验顺序才有意义。"]},{id:"signal",label:"信号镜头",accent:"#86efac",title:"前处理是在给目标离子“清场”",details:["酸化不是多余步骤，而是在先排除 CO3^2-、SO3^2- 等干扰。","NH4+ 要加碱并加热，是为了把离子形式转成可见的 NH3 证据。","KSCN 显色前也要考虑体系中价态和颜色干扰。"]},{id:"conclusion",label:"结论镜头",accent:"#fbbf24",title:"检验结论必须写成完整步骤句",details:["只写“有白色沉淀，所以有某离子”在教学上是不完整的。","应该写明前处理、加试剂、观察到的现象和最终判定。","这也是把实验语言训练成规范表达的最好入口。"]}],flowSteps:["先列干扰粒子","再做前处理","再做专属性检验","最后写成完整判定句"],boardAnchors:["前处理是在排除干扰","离子检验必须带顺序","现象和判定粒子要一一对应"],misconceptions:["不酸化就直接检 Cl- 或 SO4^2-。","只写结论不写现象。","把前处理当成可省略步骤。"],bridgeNote:"可联动无机图谱中的离子检验主线，也可接方程式库里的离子反应表达。"},pitfalls:["先后顺序写错。","忽略干扰离子。","只写现象不写判定依据。"]},{id:"precipitation-color",accent:"#22c55e",title:"沉淀与显色",tagline:"沉淀生成、颜色变化、重溶和络合共同构成高中最直观的检验现象层。",principle:"颜色、沉淀和重溶并不是孤立现象，它们反映的是粒子种类、浓度、价态和络合状态在连续变化。",signalProfile:[91,84,73,88,69,82,76],controlProfile:[{label:"现象层次感",value:94},{label:"对照清晰度",value:88},{label:"粒子回溯力",value:91}],workflow:["先辨本色与初始状态","加入试剂观察沉淀或显色","继续观察是否重溶或变色","回到粒子、价态或络合解释"],interpretation:["Fe3+ 的血红显色、Cu2+ 的蓝色体系、AgCl 的白色沉淀和氨水重溶，都属于同一类“现象反推粒子”的教学路径。","颜色和沉淀最怕只记结果不记过程，因为很多结论恰恰就藏在“先发生什么、后发生什么”里。","重溶不一定是酸溶，也可能是络合或继续反应造成的存在形态改变。"],signals:["本色","沉淀","显色","重溶","络合","氧化","对照"],typicalCase:{title:"Fe3+、Fe2+ 与 Cu2+ 的现象对比",clue:"黄色 / 浅绿色溶液、血红显色、蓝色沉淀和深蓝络离子最容易被学生混在一起。",answer:"把本色、加试剂后的显色、沉淀颜色和后续重溶过程做成并列对照，现象边界会清楚很多。"},classroomPack:{toneLabel:"现象镜头",title:"颜色与沉淀是最直接的粒子翻译",subtitle:"把本色、显色、沉淀、重溶和络合排成过程图，现象就不再只是记忆点。",lead:"一页里同时看到 Fe3+ 显血红色、Cu2+ 蓝色沉淀和 AgCl 重溶时，学生最容易建立“现象来自粒子变化”的直觉。",scenes:[{id:"sample",label:"样品镜头",accent:"#7dd3fc",title:"本色本身就已经在给线索",details:["Fe2+、Fe3+、Cu2+ 的初始颜色不一样，第一眼信息就很有价值。","如果忽略本色，只盯着后加试剂的变化，就容易把证据链切断。","本色和后续显色应始终并列对照。"]},{id:"signal",label:"信号镜头",accent:"#86efac",title:"沉淀、显色和重溶要看成连续过程",details:["Cu(OH)2 的生成和深蓝络离子的出现，本质上是在讲存在形态改变。","Fe(OH)2 到 Fe(OH)3 的变色，本质上是在讲空气氧化。","所以同一试管里“继续加试剂”后的变化极有教学价值。"]},{id:"conclusion",label:"结论镜头",accent:"#fbbf24",title:"现象结论必须回到粒子和条件",details:["看到血红色，不只要说 Fe3+，还要说明是和 KSCN 形成显色体系。","看到沉淀消失，也要说明是酸溶、络合还是继续反应。","这样现象才会变成理解，而不是只剩一个颜色词。"]}],flowSteps:["先看本色","再看显色或沉淀","继续看是否重溶或变色","回到粒子变化归纳本质"],boardAnchors:["本色、显色、沉淀要并列看","重溶不一定是酸溶","颜色变化要回到价态或络合"],misconceptions:["看到颜色就直接背结论。","把重溶都写成酸溶。","忽略继续加试剂后的第二层变化。"],bridgeNote:"可联动无机图谱里的 Fe、Cu、Ag 主线，也可接方程式库中的检验与离子表达。"},pitfalls:["只记颜色不记条件。","忽略重溶的本质。","不做前后对照。"]},{id:"titration-quantitative",accent:"#f97316",title:"滴定与定量",tagline:"终点、等当点、读数、润洗和平行实验共同决定高中定量分析是否讲得清楚。",principle:"通过定量反应把未知量转成可测体积，核心不只在公式，而在终点边界、操作规范和系统误差的来源。",signalProfile:[55,82,96,88,74,67,61],controlProfile:[{label:"终点敏感度",value:94},{label:"读数规范性",value:87},{label:"结果重复性",value:90}],workflow:["准备与润洗","选择指示剂并标定体系","靠近终点改为半滴","记录体积并回查偏差来源"],interpretation:["滴定最适合把“可见现象”和“定量边界”讲在一起，颜色突变只是外层信号，真正的核心是等当边界。","同一个结果偏大或偏小，往往可以直接追溯到某一个具体操作节点。","平行实验的意义不是重复，而是用重复性反查操作是否规范。"],signals:["颜色突变","pH 突跃","读数","半滴","平行实验","润洗","终点停留"],typicalCase:{title:"食醋总酸度测定",clue:"终点颜色太深、锥形瓶摇匀不足或读数偏差都会让结果系统偏大或偏小。",answer:"把终点前后的颜色层次、半滴操作和读数视线平齐放在同一页讲，学生最容易真正理解滴定。"},classroomPack:{toneLabel:"定量镜头",title:"终点不是一个点，而是一整段逼近过程",subtitle:"滴定课最有价值的不是算式，而是“为什么最后一滴会改写结果”。",lead:"当学生同时看到颜色突变、体积刻度和等当边界这三条线，滴定才会从公式题变成真正的定量实验。",scenes:[{id:"sample",label:"样品镜头",accent:"#7dd3fc",title:"接近终点时每半滴都很重要",details:["终点前后颜色变化通常非常敏感，越接近边界越要减慢滴速。","锥形瓶持续振荡的意义，是让局部过量现象尽快回归整体判断。","“半滴”本身就是最适合课堂放大的一个细节。"]},{id:"signal",label:"信号镜头",accent:"#86efac",title:"颜色终点和计量边界要对应起来",details:["终点是看得见的现象，等当点是化学计量边界。","指示剂的选择就是在尽量让二者重合。","只有把这两层并讲，学生才不会把终点直接等于等当点。"]},{id:"conclusion",label:"结论镜头",accent:"#fbbf24",title:"定量误差要回到具体操作",details:["未润洗、读数视线不平、气泡、摇匀不足都会改结论。","偏大还是偏小，都应该回到具体的体积关系解释。","滴定最适合训练“现象 - 操作 - 数量关系”三位一体的表达。"]}],flowSteps:["先看终点前后颜色层次","再讲终点与等当点关系","回查操作误差","最后再做定量计算"],boardAnchors:["终点是现象，等当点是边界","靠近终点必须减慢滴速","偏差必须回到具体操作解释"],misconceptions:["把终点直接等同等当点。","只会套公式不会分析偏差。","忽视润洗和读数规范。"],bridgeNote:"可联动动态原理中的滴定演示，也可接方程式库里的中和与氧化还原定量表达。"},pitfalls:["未润洗造成稀释。","终点过深。","只记结果不分析偏差来源。"]},{id:"indicator-flame",accent:"#fbbf24",title:"试纸、指示剂与焰色",tagline:"石蕊、酚酞、甲基橙、湿润试纸和焰色反应，是高中最快速也最容易被低估的检验入口。",principle:"这类快速检验依赖酸碱环境、挥发性粒子或金属激发发光的特征响应，适合做课堂第一轮筛查与对照。",signalProfile:[72,88,67,81,94,59,76],controlProfile:[{label:"对照直观度",value:92},{label:"试剂新鲜度",value:79},{label:"环境干扰控制",value:86}],workflow:["先判断是酸碱筛查还是金属筛查","选择试纸、指示剂或焰色法","保持试纸湿润或火焰洁净","用对照和二次确认锁定结论"],interpretation:["快速检验最大的价值是“先筛查、再分流”，不是用来独立承担所有结论。","焰色反应和湿润试纸都非常依赖操作条件，现象一旦不标准，结论就会被拉偏。","指示剂变色范围必须和体系边界对应，才能让颜色真正有判别意义。"],signals:["石蕊","酚酞","甲基橙","湿润试纸","焰色","pH","对照"],typicalCase:{title:"Na+、K+ 焰色与酸碱试纸联判",clue:"同样是无色溶液，若既要判断酸碱性又要判断金属离子，必须分步骤筛查。",answer:"先用试纸判断酸碱环境，再用洁净铂丝或镍铬丝做焰色，并用钴玻璃辅助识别 K+。"},classroomPack:{toneLabel:"快检镜头",title:"快速检验不是简单，但它最能打通第一眼判断",subtitle:"试纸、指示剂和焰色反应的价值，在于为后续专检快速分流。",lead:"看到试纸变色、闻到 NH3、看到黄色或紫色焰色时，学生最容易感受到“化学证据就在眼前”。",scenes:[{id:"sample",label:"样品镜头",accent:"#7dd3fc",title:"第一轮筛查先把范围缩小",details:["酸碱性、挥发性和金属离子类别都可以先用快速检验缩小范围。","这一步不是终判，而是给后续专检搭桥。","如果第一轮筛查做得清楚，后面很多检验题会轻松很多。"]},{id:"signal",label:"信号镜头",accent:"#86efac",title:"快检现象高度依赖操作细节",details:["湿润试纸的位置、焰色用丝是否洁净、是否借助钴玻璃，都会影响结论。","指示剂本身也有变色范围，不能脱离 pH 区间去硬记颜色。","所以快检尤其适合做“标准操作 vs 错误操作”的并排展示。"]},{id:"conclusion",label:"结论镜头",accent:"#fbbf24",title:"快检负责分流，专检负责锁定",details:["焰色和试纸给的是快速入口，不应替代全部检验步骤。","快检后的二次确认，才构成真正可靠的教学闭环。","把快检和专检分层讲，会明显提升课堂理解度。"]}],flowSteps:["先做快筛","再控制操作条件","再做二次确认","最后归纳为什么快检不能替代专检"],boardAnchors:["快检负责分流，不负责包办结论","试纸和焰色都依赖操作规范","指示剂颜色必须回到变色范围"],misconceptions:["把快检当成最终结论。","焰色操作不规范。","试纸不湿润或位置放错。"],bridgeNote:"可联动元素周期表中的 Na、K、Cu 等元素，也可接无机图谱中的显色与离子检验主线。"},pitfalls:["焰色丝不洁净。","试纸位置与湿润条件错误。","把指示剂颜色硬记成绝对结论。"]}],l={"gas-detection":{reagentRoles:["石灰水负责 CO2 的二次证据判定，不能直接拿来区分所有放气体系。","品红和酸性 KMnO4 主要用于 SO2 一类还原性气体的判别。","湿润红色石蕊试纸、浓盐酸白烟适合和 NH3 一起成对出现。","带火星木条和燃着木条分工不同，前者常判 O2，后者常配合 H2 或可燃性气体。"],observationFocus:["先记初始颜色和气味，再看检验液或试纸变化。","NO、NO2 的区别一定要把空气是否参与写出来。","“先除干扰、后做二次确认”是气体检验最容易拉开层次的一步。"],interferenceList:["SO2 和 Cl2 都可能让有色物质褪色，但机理和区分方式不同。","CO2 与 SO2 都可让石灰水浑浊，顺序和前处理必须先做清楚。","可燃气体若不验纯就点燃，会把安全问题和现象判断一起搞乱。"],expressionAnchors:["检验某气体时，要先写前处理，再写试剂和现象。","气体结论通常至少要有两层证据，尤其是存在干扰时。","尾气吸收与防倒吸本身也是装置表达的一部分。"],deviceFocus:["发生、净化、收集、检验、吸收要沿气流方向连续排开。","易溶于水气体或有毒气体的尾端安排不能省略。","检验气体前常需先排净空气，否则颜色判断容易失真。"],linkedViews:[{id:"inorganic-map",label:"无机图谱"},{id:"equation-library",label:"方程式库"},{id:"dynamic-principles",label:"动态原理"}]},"ion-analysis":{reagentRoles:["AgNO3 / HNO3 常用于 Cl- 检验，酸化的作用是先排除 CO3^2-、SO3^2- 干扰。","Ba2+ 常用于 SO4^2- 检验，但也需要前处理避免假阳性。","NaOH、加热、湿润红色石蕊试纸组成 NH4+ 的完整检验链。","KSCN 是 Fe3+ 的经典显色试剂，但需要考虑体系中 Fe2+ 或其它颜色干扰。"],observationFocus:["离子检验一定要把前处理和专检连在一起看。","同样是白色沉淀，也要继续问“是哪种白色沉淀、是否还能继续处理”。","显色和放气都应当与目标离子一一对应，不可只报结论。"],interferenceList:["不先酸化就直接检 Cl-、SO4^2-，最容易把碳酸根、亚硫酸根带进结果。","Fe3+ 显色前若本底颜色过深，也会影响现象辨认。","离子检验若只做一步，常常只能得到“疑似”，不能得到“锁定”。"],expressionAnchors:["离子检验结论必须包含前处理、试剂、现象、判定四要素。","“有白色沉淀”只是现象，“含某离子”才是判定，中间不能跳步。","试剂顺序写反，会让整句结论失效。"],deviceFocus:["试管实验最怕步骤混乱，因此并列演示顺序尤其重要。","NH4+ 检验时试纸位置、加热位置和试管口方向都直接影响效果。","离子检验若做成对照组，教学说服力会显著提升。"],linkedViews:[{id:"inorganic-map",label:"无机图谱"},{id:"equation-library",label:"方程式库"},{id:"periodic-table",label:"元素周期表"}]},"precipitation-color":{reagentRoles:["OH- 常触发金属离子沉淀，NH3 既可生成沉淀也可进一步参与络合。","KSCN 负责 Fe3+ 显色，AgNO3 负责卤离子沉淀，二者都属于“把无色信息变成有色证据”。","酸和络合剂并不总是“溶解沉淀”，还可能改写粒子存在形态。"],observationFocus:["要同时看本色、加试剂后的第一层变化和继续处理后的第二层变化。","颜色变化要和价态、络合或氧化条件对应起来。","重溶现象最适合和“为什么自由离子浓度变了”一起讲。"],interferenceList:["血红色、蓝色、黄褐色都可能因为本色或显色叠加而看起来相近，需要对照。","沉淀消失不一定是酸溶，也可能是络合重溶。","若不保留前后对照，学生很难分清“本色”和“显色”两层含义。"],expressionAnchors:["现象表达要写出“先出现什么，再出现什么”。","显色结论要回到参与的离子和试剂，不宜只说颜色。","沉淀与重溶最好写成连续过程句，而不是拆成孤立结论。"],deviceFocus:["并排试管和对照组是显色、沉淀教学里最重要的显示方式。","继续加试剂的过程比终点画面更有教学价值。","白色背景和同光源条件更利于颜色辨认。"],linkedViews:[{id:"inorganic-map",label:"无机图谱"},{id:"periodic-table",label:"元素周期表"},{id:"equation-library",label:"方程式库"}]},"titration-quantitative":{reagentRoles:["标准溶液负责提供定量边界，指示剂负责把边界变成可见信号。","酚酞、甲基橙等指示剂各有变色范围，必须和反应体系匹配。","待测液、标准液、洗液之间的角色不能混淆，尤其是润洗环节。"],observationFocus:["终点前后的颜色层次是最值得放大展示的局部过程。","读数视线、锥形瓶振荡和是否有气泡都会改写体积判断。","平行实验不是重复动作，而是在用重复性检验操作质量。"],interferenceList:["终点颜色过深会导致结果偏大，未润洗常会带来系统误差。","把终点直接等于等当点，会让很多滴定图像和误差题全部混乱。","只会代公式不会回查操作，是滴定教学里最常见的断层。"],expressionAnchors:["定量结论要同时写体积关系和误差方向。","滴定的核心表达不是“算出多少”，而是“为什么这么算、为什么会偏”。","图像、现象和数量关系最好始终并列出现。"],deviceFocus:["滴定管零刻度在上，读数方向与一般量筒相反，必须单独强调。","润洗、排气泡、视线平齐、半滴操作是展示页必须放大的关键动作。","终点停留时间和颜色深浅都适合做并排对照。"],linkedViews:[{id:"dynamic-principles",label:"动态原理"},{id:"equation-library",label:"方程式库"},{id:"inorganic-map",label:"无机图谱"}]},"indicator-flame":{reagentRoles:["石蕊、酚酞、甲基橙分别负责不同酸碱范围的快速筛查。","湿润试纸适合放大 NH3、Cl2 等挥发性粒子对环境的影响。","焰色反应依赖洁净金属丝、无色火焰和必要的钴玻璃辅助。"],observationFocus:["试纸和指示剂的颜色变化必须回到具体 pH 或粒子环境。","焰色应和空白火焰、标准样并列展示，避免环境光干扰。","快检最大的价值是分流，不是直接完成全部判定。"],interferenceList:["试纸不湿润或放置位置错误时，现象很容易偏弱甚至消失。","Na 的黄色焰色容易覆盖 K 的紫色，需要借助钴玻璃或对照。","指示剂变色范围不同，不能把不同体系里的颜色变化混写。"],expressionAnchors:["快检结论后最好补一个二次确认步骤，形成完整证据链。","焰色结论要写清是“观察到某颜色焰色”，而不是直接跳到离子名。","指示剂结论必须带体系环境，不能离开酸碱条件单独存在。"],deviceFocus:["焰色实验要优先保证丝洁净、火焰洁净、背景清楚。","试纸放置位置很关键，既不能离得过远，也不能直接浸入液体。","快检最适合做标准操作与错误操作对照板。"],linkedViews:[{id:"periodic-table",label:"元素周期表"},{id:"inorganic-map",label:"无机图谱"},{id:"equation-library",label:"方程式库"}]}},i=[{id:"so2-cl2-contrast",title:"SO2 与 Cl2 对照",accent:"#38bdf8",summary:"这两种气体都会让有色物质变化，但本质、现象恢复性和判别顺序都不同。",scenes:["SO2 可使品红褪色且加热恢复，Cl2 的漂白通常不靠加热恢复。","两者都可能影响试纸或颜色判断，因此最适合做并排对照演示。","把褪色现象直接等同漂白，是高中检验教学里最常见的误区之一。"],boardLines:["SO2 的褪色常为可逆，Cl2 / HClO 的漂白常不可逆","同样是褪色，必须回到粒子和机理判断","最好的讲法是做并列对照而不是分开硬背"],boundaries:["要写清是用品红还是其它有色物质","是否加热恢复是关键分界点","先后顺序不清时很容易把结论讲混"],linkedViews:[{id:"inorganic-map",label:"无机图谱"},{id:"equation-library",label:"方程式库"}]},{id:"chloride-sulfate-order",title:"Cl- 与 SO4^2- 顺序",accent:"#8b5cf6",summary:"离子检验中最值得单独拉出来讲的一块，就是酸化和加试剂的顺序。",scenes:["不先酸化就直接加 AgNO3 或 Ba2+，最容易把 CO3^2-、SO3^2- 干扰带进来。","同样的白色沉淀，在不同前处理后代表的结论完全不同。","顺序一旦错，后面的现象即使“看到了”，也不能直接作为判定依据。"],boardLines:["先酸化，再做专检","同一白色沉淀不等于同一离子","离子检验的核心之一就是干扰排除"],boundaries:["前处理和专检必须合并讲","结论要写成完整步骤句","白色沉淀最好做继续处理或对照说明"],linkedViews:[{id:"inorganic-map",label:"无机图谱"},{id:"periodic-table",label:"元素周期表"}]},{id:"fe-cu-color-system",title:"Fe / Cu 颜色体系",accent:"#22c55e",summary:"本色、显色、沉淀和络合全部压在 Fe、Cu 体系里，是最适合做现象对照的一组内容。",scenes:["Fe2+、Fe3+、Cu2+ 初始颜色不同，后加试剂后的现象也完全不同。","Fe3+ 与 KSCN、Cu2+ 与 OH- / NH3 的变化最适合做分屏对照。","讲这组内容时，前后对照比单独讲某一个试管更有解释力。"],boardLines:["本色不是背景信息，而是第一层证据","显色和沉淀要区分参与试剂","重溶常和络合有关，不宜一律写成酸溶"],boundaries:["要保留初始状态","要展示继续加试剂后的第二层变化","要把颜色回到价态或络合解释"],linkedViews:[{id:"inorganic-map",label:"无机图谱"},{id:"periodic-table",label:"元素周期表"}]},{id:"ammonium-ammonia-chain",title:"铵盐与氨链条",accent:"#f97316",summary:"NH4+、NH3、湿润试纸和白烟是高中最值得做连续演示的一条检验链。",scenes:["加碱并加热后放出 NH3，是从离子形式转到气体形式的典型演示。","湿润红色石蕊试纸变蓝和与 HCl 形成白烟可以连续接在一起。","这一条链能把离子检验、气体检验和酸碱环境同时打通。"],boardLines:["NH4+ 检验常写“加碱并加热”","NH3 使湿润红色石蕊试纸变蓝","NH3 与 HCl 可形成白烟"],boundaries:["不加热时现象可能不明显","试纸需要湿润且位置要合适","铵盐检验与氨气检验应当连成一条线讲"],linkedViews:[{id:"inorganic-map",label:"无机图谱"},{id:"equation-library",label:"方程式库"}]},{id:"flame-test-focus",title:"焰色与快检边界",accent:"#fbbf24",summary:"焰色反应看似简单，其实最适合用来讲“快检负责分流，专检负责锁定”。",scenes:["Na 呈黄色、K 呈紫色，最适合放在白底下做并排对照。","Na 的黄色容易干扰 K 的紫色，因此钴玻璃和对照组都很关键。","焰色结果不应单独承担全部结论，应和其它检验共同使用。"],boardLines:["焰色适合做快速筛查","K+ 的焰色常需借助钴玻璃观察","快检后最好安排二次确认"],boundaries:["金属丝必须洁净","背景光和火焰颜色会影响观察","快检和专检不应混成一步"],linkedViews:[{id:"periodic-table",label:"元素周期表"},{id:"inorganic-map",label:"无机图谱"}]}];export{e as A,i as a,l as b};
